<script lang="ts">import { avatarClassName,type AvatarStyleProps } from '@fex-design/styles/avatar';import { cn } from '@fex/utils';import { onDestroy,setContext,type Snippet } from 'svelte';import type { HTMLAttributes } from 'svelte/elements';import { avatarContextKey,createAvatarContext } from './context';interface Props extends Omit<HTMLAttributes<HTMLSpanElement>,'class'>,AvatarStyleProps{class?:string;children?:Snippet}let{class:className,children,size='md',shape='circle',...rest}:Props=$props();const context=createAvatarContext();setContext(avatarContextKey,context);onDestroy(()=>context.controller.reset())</script>
